DO $$ BEGIN CREATE TYPE public.verification_type AS ENUM ('phone','identity','liveness','malaysia_presence','entity_registration','representative_authority','licence','official_source'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.verification_status AS ENUM ('not_started','pending','verified','rejected','expired','revoked','suspended'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.verification_source AS ENUM ('user_submitted','manual_review','official_registry','provider_assertion','system_check','admin_review'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.user_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,verification_type public.verification_type NOT NULL,status public.verification_status NOT NULL DEFAULT 'not_started',source public.verification_source NOT NULL,checked_at timestamptz,recheck_at timestamptz,expires_at timestamptz,reviewed_by uuid REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.entity_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES public.entities(id) ON DELETE CASCADE,verification_type public.verification_type NOT NULL,status public.verification_status NOT NULL DEFAULT 'not_started',source public.verification_source NOT NULL,checked_at timestamptz,recheck_at timestamptz,expires_at timestamptz,reviewed_by uuid REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.verification_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_verification_id uuid REFERENCES public.user_verifications(id) ON DELETE CASCADE,entity_verification_id uuid REFERENCES public.entity_verifications(id) ON DELETE CASCADE,provider_reference text,document_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,review_notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT verification_evidence_subject CHECK ((user_verification_id IS NULL) <> (entity_verification_id IS NULL)));
CREATE INDEX IF NOT EXISTS user_verification_subject_idx ON public.user_verifications(user_id,verification_type,status);CREATE INDEX IF NOT EXISTS entity_verification_subject_idx ON public.entity_verifications(entity_id,verification_type,status);CREATE INDEX IF NOT EXISTS verification_evidence_user_idx ON public.verification_evidence(user_verification_id);CREATE INDEX IF NOT EXISTS verification_evidence_entity_idx ON public.verification_evidence(entity_verification_id);
ALTER TABLE public.user_verifications ENABLE ROW LEVEL SECURITY;ALTER TABLE public.entity_verifications ENABLE ROW LEVEL SECURITY;ALTER TABLE public.verification_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_verification_self_read ON public.user_verifications FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_system_role(ARRAY['MODERATOR','SUPER_ADMIN']::public.user_role[]));
CREATE POLICY entity_verification_summary_read ON public.entity_verifications FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.entities e WHERE e.id=entity_id AND e.owner_user_id=auth.uid()) OR public.has_system_role(ARRAY['MODERATOR','SUPER_ADMIN']::public.user_role[]));
CREATE POLICY verification_evidence_privileged_read ON public.verification_evidence FOR SELECT TO authenticated USING (public.has_system_role(ARRAY['MODERATOR','SUPER_ADMIN']::public.user_role[]));
GRANT SELECT ON public.user_verifications,public.entity_verifications,public.verification_evidence TO duta_app;
